import re, ast, statistics
lines=open('/workspace/outputs/driver.log', errors='replace').read().splitlines()
rolls={}
perfs=[]
for ln in lines:
    m=re.search(r"\] log_utils\.py:\d+ - rollout (\d+): (\{.*\})", ln)
    if m:
        rolls[int(m.group(1))]=ast.literal_eval(m.group(2))
    m=re.search(r"\] train_metric_utils\.py:\d+ - perf (\d+): (\{.*\})", ln) or re.search(r"log_perf_data_raw.*?perf (\d+): (\{.*\})", ln)
    if m:
        perfs.append((int(m.group(1)), ast.literal_eval(m.group(2))))
# generic perf search
if not perfs:
    for ln in lines:
        m=re.search(r"perf (\d+): (\{.*\})", ln)
        if m:
            perfs.append((int(m.group(1)), ast.literal_eval(m.group(2))))
print('rollouts', len(rolls), 'minmax', min(rolls), max(rolls))
print('perflines', len(perfs), 'ids', sorted(set(x[0] for x in perfs))[:5], sorted(set(x[0] for x in perfs))[-5:])
ks=['rollout/response_lengths','rollout/truncated','rollout/raw_reward','rollout/log_probs','rollout/ref_log_probs','rollout/rollout_log_probs','rollout/advantages']
print('step  '+'  '.join(f'{k.split("/")[1][:12]:>12}' for k in ks))
for i in sorted(rolls):
    if i%5==0 or i in (0,1,2,3,4,91):
        d=rolls[i]
        print(f'{i:4d}  '+'  '.join(f'{d.get(k,float("nan")):12.5f}' for k in ks))
