import re, ast, statistics as st
P={}
for ln in open('outputs/driver.log', errors='replace'):
    m=re.search(r"perf (\d+): (\{.*\})", ln)
    if m:
        try: P.setdefault(int(m.group(1)),{}).update(ast.literal_eval(m.group(2)))
        except Exception: pass
def series(k):
    return [(r,d[k]) for r,d in sorted(P.items()) if k in d]
for k in ['rollout/fully_async/stale_groups_recycled','perf/rollout_time','perf/tokens_per_gpu_per_sec','rollout/truncated_ratio','rollout/response_len/mean','rollout/zero_std/all_one_percentage','rollout/zero_std/count_-1.0','rollout/zero_std/all_zero_percentage']:
    s=series(k)
    if not s: print(k,'MISSING'); continue
    vals=[v for _,v in s]
    print(f"{k}: n={len(vals)} first={vals[0]:.4g} last={vals[-1]:.4g} mean={sum(vals)/len(vals):.4g} min={min(vals):.4g} max={max(vals):.4g}")
s=series('rollout/fully_async/stale_groups_recycled')
print("total stale", sum(v for _,v in s), "steps with>0", sum(1 for _,v in s if v>0))
PY

