arguments.command:
python3 -I - <<'PY'
import re, ast
T=[]
for ln in open('outputs/driver.log', errors='replace'):
    m=re.search(r"step (\d+): (\{.*'train/.*\})", ln)
    if m:
        try: T.append((int(m.group(1)), ast.literal_eval(m.group(2))))
        except Exception: pass
print("n train lines", len(T))
if T:
    print("keys", sorted(T[0][1].keys()))
    for i in [0,1,2,45,90,91]:
        if i < len(T): print(T[i][0], {k:round(v,6) if isinstance(v,float) else v for k,v in T[i][1].items()})
    import statistics as st
    for k in ['train/loss','train/pg_loss','train/grad_norm','train/ppo_kl','train/pg_clipfrac','train/tis','train/tis_abs','train/entropy_loss']:
        vs=[d[k] for _,d in T if k in d]
        if vs: print(k,'mean',round(sum(vs)/len(vs),6),'min',round(min(vs),6),'max',round(max(vs),6))
PY

