arguments.command:
python3 -I - <<'PY'
import re, ast
P={}
for ln in open('outputs/driver.log', errors='replace'):
    m=re.search(r"perf (\d+): (\{.*\})", ln)
    if m:
        try: P.setdefault(int(m.group(1)),{}).update(ast.literal_eval(m.group(2)))
        except Exception: pass
for r in [0,1,2,45,91]:
    d=P[r]
    print(r, {k:round(d.get(k,float('nan')),3) for k in ['perf/tokens_per_gpu_per_sec','perf/effective_tokens_per_gpu_per_sec','perf/longest_effective_sample_tokens_per_sec','rollout/prefix_cache_hit_rate','rollout/repetition_frac','rollout/avg_cached_tokens_per_sample','perf/train_wait_time','perf/actor_train_time','perf/log_probs_time','perf/ref_log_probs_time']})
PY

